INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷80·晋高祖纪·天福六年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/85c74eda9d678a1a70ddae003a8d3b3ce4e7932a/content/books/zizhi-tongjian/vol-282/year-0941/part-04/sources/library/jiuwudaishi-080-941-eighth-month/source.txt", "note": "《旧五代史》卷80·晋高祖纪·天福六年八月，段落 jiu-wudaishi-205deb4a7860-p001961；已核上下文及传主，纸本及异文待核。", "id": "70a9d596-0f2e-5c61-ae53-ceeb4a15a24d"}, {"title": "新五代史·卷67·吴越世家·钱弘佐继位年龄", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/85c74eda9d678a1a70ddae003a8d3b3ce4e7932a/content/books/zizhi-tongjian/vol-282/year-0941/part-04/sources/library/xinwudaishi-067-hongzuo-age/source.txt", "note": "《新五代史》卷67·吴越世家·钱弘佐继位年龄，段落 xin-wudaishi-b08f244b9241-p003372；已核上下文及传主，纸本及异文待核。", "id": "85a080d0-6f1e-5fce-bc41-5c374b6c938b"}, {"title": "新五代史·卷67·吴越世家·钱元瓘火灾与患病", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/85c74eda9d678a1a70ddae003a8d3b3ce4e7932a/content/books/zizhi-tongjian/vol-282/year-0941/part-04/sources/library/xinwudaishi-067-wuyue-fire/source.txt", "note": "《新五代史》卷67·吴越世家·钱元瓘火灾与患病，段落 xin-wudaishi-b08f244b9241-p003371；已核上下文及传主，纸本及异文待核。", "id": "385b0ef8-0462-57d2-b6ed-e70b3ef5d542"}, {"title": "资治通鉴·卷282·天福六年七月至九月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7c62fad39b7b2dadda562d9e710f8d8f62f5bdf/content/books/zizhi-tongjian/vol-282/year-0941/part-03/sources/library/tongjian-282-941-autumn/source.txt", "note": "《资治通鉴》卷282·天福六年七月至九月，段落 zizhi-tongjian-a63549944a71-p003357；已核上下文及传主，纸本及异文待核。", "id": "8df5067c-54a1-557d-844e-ef63343f76fd"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "潘承祐", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇武军节度判官，晋江人。王延羲与王延政交战时，多次劝王延政停战修好；王延政向闽王使者展示军队、言语傲慢时，潘承祐长跪劝谏，受到威胁仍继续进谏。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "709be4ea-d9bd-5e7a-b136-9452103cf994"}, {"name": "王继严", "aliases": ["王繼嚴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继严，建王、权判六军诸卫获任者。", "biography": null, "status": "draft", "id": "d482c47e-008e-5701-bfc0-af64dfe325d7"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}, {"name": "安从进", "aliases": ["安從進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安从进，受询的侍卫都指挥使。", "biography": null, "status": "draft", "id": "3b1f48e5-6ce0-58cd-add7-1bdf9f0d4812"}, {"name": "章德安", "aliases": ["章徳安"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越内都监，处州人。941年钱传瓘临终时，建议让年轻的钱弘佐继位，并受托辅佐。钱传瓘死后，暂不公布死讯，与诸将商议后拘杀被告谋立钱弘侑的戴恽。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "cf63861a-a3c1-5d02-bf95-1f9e4631550f"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "戴恽", "aliases": ["戴惲"], "era": "五代十国", "birth_year": null, "death_year": 941, "description": "吴越内牙指挥使，曾受钱传瓘信任，受委掌管军事。戴恽妻子与钱弘侑的乳母有亲属关系。941年钱传瓘去世后，戴恽被告谋立钱弘侑，八月壬子入府时被伏兵拘杀。告发不等于谋立已经查实，出生年未载。", "biography": null, "status": "draft", "id": "7599076a-bdeb-51ec-a7ab-333505143b73"}, {"name": "钱弘侑", "aliases": ["錢弘侑", "孙弘侑", "孫弘侑"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘的养子，本姓孙。941年钱传瓘去世后，有人告发戴恽谋立钱弘侑；章德安与诸将拘杀戴恽，钱弘侑被废为平民，恢复孙姓并幽禁明州。生卒年未载。", "biography": null, "status": "draft", "id": "6148e6f2-24d2-5db3-874b-73c6d6987ca7"}, {"name": "曹仲达", "aliases": ["曹仲達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：曹仲达，处州刺史、权知政事者。", "biography": null, "status": "draft", "id": "510a0a94-ad3f-53ed-bcbc-04bd2a897461"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "吴越府署失火，宫室和府库几乎烧尽", "start_year": 941, "end_year": 941, "time_original": "941年七月条下，具体日期未载", "dynasty": "五代十国", "description": "吴越府署失火，宫室和府库几乎烧尽。", "phases": [], "location_name": "吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "714bfa72-d3f8-5b80-81cf-9a205c2ffe8c"}, {"title": "钱传瓘因火灾惊惧而患病", "start_year": 941, "end_year": 941, "time_original": "941年七月条下，具体日期未载", "dynasty": "五代十国", "description": "钱传瓘因吴越府署火灾惊惧，患上史书所称的狂疾。", "phases": [], "location_name": "吴越", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1c7d7ea4-b642-5253-a5d7-94a5aed5506d"}, {"title": "南唐有人建议李昪乘吴越灾后衰弱攻取吴越", "start_year": 941, "end_year": 941, "time_original": "941年七月条下，具体日期未载", "dynasty": "五代十国", "description": "南唐有人建议李昪乘吴越灾后衰弱攻取吴越。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3ce31c5f-8af9-5110-945a-38bfaba35a62"}, {"title": "李昪拒绝乘吴越火灾攻取其地", "start_year": 941, "end_year": 941, "time_original": "941年七月条下，具体日期未载", "dynasty": "五代十国", "description": "李昪说，不能利用别人的灾难获利，拒绝乘吴越灾后衰弱出兵的建议。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3d966cfc-39ea-553f-b3d6-531fe9e01e53"}, {"title": "李昪派使者慰问吴越，并帮助补足灾后所缺", "start_year": 941, "end_year": 941, "time_original": "941年七月条下，具体